<script setup lang="ts">import type {CPM,Task} from '../types/domain';import {num} from '../utils/format';defineProps<{baseline:CPM;tasks:Task[]}>()</script><template><div class="table-scroll"><table><thead><tr><th>任务</th><th>m / h</th><th>ES</th><th>EF</th><th>LS</th><th>LF</th><th>总时差 / h</th><th>基线关键</th></tr></thead><tbody><tr v-for="t in baseline.tasks" :key="t.task_id" :class="{critical:t.critical}"><td><b>{{t.task_id}}</b> {{tasks.find(n=>n.task_id===t.task_id)?.name}}</td><td>{{num(t.duration)}}</td><td>{{num(t.es)}}</td><td>{{num(t.ef)}}</td><td>{{num(t.ls)}}</td><td>{{num(t.lf)}}</td><td>{{num(t.total_float)}}</td><td>{{t.critical?'关键':'非关键'}}</td></tr></tbody></table></div></template>